INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Planung?', 2, '[{"text": "Nein", "correct": true, "because": "Planen ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Strukturierter Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Planen", "correct": true, "because": "Ziele und Umfang festlegen"}, {"text": "Durchführen", "correct": false, "because": "Folgt der Planung"}, {"text": "Feedback sammeln", "correct": false, "because": "Später im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Zyklus?', 5, '[{"text": "Prototyp entwickeln", "correct": true, "because": "Lösungen testen"}, {"text": "Verbessern", "correct": true, "because": "Anpassungen vornehmen"}, {"text": "Einmalige Planung", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback wird gesammelt. b) Verbessern ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verbessern essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesem Ablauf?', 4, '[{"text": "Feedback sammeln", "correct": false, "because": "Basis für Verbesserung"}, {"text": "Prototyp entwickeln", "correct": false, "because": "Testbare Lösungen"}, {"text": "Lineare Entwicklung", "correct": true, "because": "Iterativ aufgebaut"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal Feedback hole?', 2, '[{"text": "Nein", "correct": true, "because": "Feedback in jedem Zyklus"}, {"text": "Ja", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um Lösungen zu testen?', 3, '[{"text": "Durchführen oder Prototyp entwickeln", "correct": true, "because": "Prototypen erstellen"}, {"text": "Feedback sammeln", "correct": false, "because": "Rückmeldung einholen"}, {"text": "Verbessern", "correct": false, "because": "Anpassungen vornehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern die Anpassung?', 5, '[{"text": "Feedback sammeln", "correct": true, "because": "Rückmeldung nutzen"}, {"text": "Verbessern", "correct": true, "because": "Optimierung umsetzen"}, {"text": "Einmalige Tests", "correct": false, "because": "Zyklisch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Planen startet den Zyklus. b) Feedback ist unwichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Prototyp entwickeln", "correct": false, "because": "Lösungen testen"}, {"text": "Verbessern", "correct": false, "because": "Anpassung zentral"}, {"text": "Feste Endpunkte", "correct": true, "because": "Iterative Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verbessere ich hier nur einmal?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Zyklus verbessert"}, {"text": "Ja", "correct": false, "because": "Iterativer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente unterstützen die Entwicklung?', 4, '[{"text": "Prototyp entwickeln", "correct": true, "because": "Ideen ausprobieren"}, {"text": "Feedback sammeln", "correct": true, "because": "Rückmeldung einholen"}, {"text": "Lineare Prozesse", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Prototypen arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Prototypen sind Kern"}, {"text": "Ja", "correct": false, "because": "Testen von Lösungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich nach der Planung?', 3, '[{"text": "Durchführen oder Prototyp entwickeln", "correct": true, "because": "Umsetzung starten"}, {"text": "Verbessern", "correct": false, "because": "Später im Zyklus"}, {"text": "Feedback sammeln", "correct": false, "because": "Nach Prototyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback führt zu Verbesserung. b) Planen ist einmalig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Planen iterativ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Iterative Anpassung"}, {"text": "Kundeneinbindung", "correct": true, "because": "Feedback nutzen"}, {"text": "Feste Ergebnisse", "correct": false, "because": "Dynamisch entwickelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Feedback sammeln", "correct": false, "because": "Basis für Verbesserung"}, {"text": "Prototyp entwickeln", "correct": false, "because": "Testbare Lösungen"}, {"text": "Einmalige Entwicklung", "correct": true, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Feedback hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Kern der Anpassung"}, {"text": "Ja", "correct": false, "because": "Rückmeldung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal plane?', 2, '[{"text": "No", "correct": true, "because": "Planen in jedem Zyklus"}, {"text": "Yes", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach dem Prototyp?', 4, '[{"text": "Feedback sammeln", "correct": true, "because": "Rückmeldung einholen"}, {"text": "Planen", "correct": false, "because": "Vor Prototyp"}, {"text": "Durchführen", "correct": false, "because": "Bereits gemacht"}]');
